def check_graph(edges, n_vertices):
    adj = {i: [] for i in range(n_vertices)}
    for i in range(0, len(edges), 2):
        u, v = edges[i], edges[i+1]
        adj[u].append(v)
        adj[v].append(u)

    # check girth
    girth = float('inf')
    for i in range(n_vertices):
        dist = {i: 0}
        parent = {i: -1}
        q = [i]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    girth = min(girth, dist[u] + dist[v] + 1)

    print("Girth:", girth)
    print("Edges:", len(edges)//2)

